.venv/bin/python -c "
from django.contrib.auth.validators import ASCIIUsernameValidator, UnicodeUsernameValidator
for v in (ASCIIUsernameValidator(), UnicodeUsernameValidator()):
    try:
        v('valid.user-1')
        ok1 = True
    except Exception:
        ok1 = False
    try:
        v('bad\n')
        ok2 = False
    except Exception:
        ok2 = True
    print(type(v).__name__, 'plain ok:', ok1, 'newline rejected:', ok2)
"

